#include <cstdio>
#include <string>
#include <vector>
#include <queue>
#include <sstream>
#include <iostream>

struct Node {
    int val;
    Node *left, *right;
    Node(int v) : val(v), left(nullptr), right(nullptr) {}
};

int main() {
    std::string line;
    std::getline(std::cin, line);
    std::istringstream iss(line);
    std::vector<std::string> tok;
    std::string t;
    while (iss >> t) tok.push_back(t);
    if (tok.empty() || tok[0] == "null") { printf("\n"); return 0; }

    std::vector<Node*> nodes(tok.size(), nullptr);
    nodes[0] = new Node(std::stoi(tok[0]));
    std::queue<int> q;
    q.push(0);
    size_t i = 1;
    while (!q.empty() && i < tok.size()) {
        int idx = q.front(); q.pop();
        if (i < tok.size()) {
            if (tok[i] != "null") {
                nodes[i] = new Node(std::stoi(tok[i]));
                nodes[idx]->left = nodes[i];
                q.push((int)i);
            }
            ++i;
        }
        if (i < tok.size()) {
            if (tok[i] != "null") {
                nodes[i] = new Node(std::stoi(tok[i]));
                nodes[idx]->right = nodes[i];
                q.push((int)i);
            }
            ++i;
        }
    }
    std::queue<Node*> bfs;
    bfs.push(nodes[0]);
    while (!bfs.empty()) {
        int sz = (int)bfs.size();
        for (int k = 0; k < sz; ++k) {
            Node* cur = bfs.front(); bfs.pop();
            if (k) printf(" ");
            printf("%d", cur->val);
            if (cur->left) bfs.push(cur->left);
            if (cur->right) bfs.push(cur->right);
        }
        printf("\n");
    }
    return 0;
}
